language "moriarty-sherlock-draft/1";
program P {
  fn a(n: UInt): UInt { n + 1 }
  fn b(n: UInt): UInt { n + 2 }
  fn c(n: UInt): UInt { b(n) }
  entry c(1);
}

language "moriarty-sherlock-draft/1";
program P {
  fn same(t: Tree): Bool { t == t }
  entry same(branch(leaf(4), leaf(4)));
}
